def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = opp_d = my_c = my_d = 0
    recent_len = min(n, 12)
    recent_start = n - recent_len
    recent_opp_c = recent_my_c = recent_my_d = 0
    last_my_d = -1

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
            last_my_d = i
        if i >= recent_start:
            if b == 'C':
                recent_opp_c += 1
            if a == 'C':
                recent_my_c += 1
            else:
                recent_my_d += 1

    after_d_total = after_d_c = after_c_total = after_c_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            after_d_total += 1
            if history[i + 1][1] == 'C':
                after_d_c += 1
        else:
            after_c_total += 1
            if history[i + 1][1] == 'D':
                after_c_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if opp_c == 0:
        if n >= 30 and rng.random() < 0.01:
            return 'C'
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 92 and rng.random() < 0.1:
                return 'D'
            if n >= 97:
                return 'D'
            return 'C'
        if n - last_my_d >= 2:
            return 'D'
        return 'C'

    my_last, opp_last = history[-1]
    opp_rate = opp_c / float(n)
    recent_rate = recent_opp_c / float(recent_len)

    recent_c_d = 0
    for i in range(max(0, n - 4), n):
        if history[i][0] == 'C' and history[i][1] == 'D':
            recent_c_d += 1

    small_recent_my_d = 0
    for i in range(max(0, n - 3), n):
        if history[i][0] == 'D':
            small_recent_my_d += 1

    if recent_opp_c == 0:
        if opp_rate < 0.5:
            return 'D'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if opp_rate < 0.45 or opp_d_streak >= 5:
            if rng.random() < 0.95:
                return 'D'
            return 'C'

        if small_recent_my_d > 0:
            if opp_rate > 0.75 and recent_rate > 0.55:
                p = 0.55
            else:
                p = 0.30
        else:
            if opp_rate > 0.9:
                p = 0.45
            elif opp_rate > 0.75:
                p = 0.18
            else:
                p = 0.05
            if opp_d_streak == 1 and recent_c_d <= 1 and recent_rate > 0.85:
                p += 0.25

        if opp_d_streak >= 3:
            p -= 0.25
        if my_last == 'D':
            p += 0.15
        if recent_rate > 0.85:
            p += 0.10
        if after_d_total >= 2 and after_d_c / float(after_d_total) > 0.5 and recent_rate > 0.75:
            p += 0.08
        if after_c_total >= 2 and after_c_d / float(after_c_total) > 0.2 and opp_rate < 0.95:
            p -= 0.15
        if recent_c_d >= 2:
            p = min(p, 0.12)

        if p < 0.0:
            p = 0.0
        if p > 1.0:
            p = 1.0

        return 'C' if rng.random() < p else 'D'

    if my_last == 'D':
        forgive_rate = 0.0
        if after_d_total >= 2:
            forgive_rate = after_d_c / float(after_d_total)
        unprovoked_rate = 0.0
        if after_c_total >= 2:
            unprovoked_rate = after_c_d / float(after_c_total)

        if recent_rate >= 0.95 and opp_rate > 0.8 and forgive_rate > 0.4 and recent_my_d >= 2:
            if rng.random() < 0.2:
                return 'D'
        return 'C'

    exploit = 0.0

    forgive_rate = 0.0
    if after_d_total >= 2:
        forgive_rate = after_d_c / float(after_d_total)

    unprovoked_rate = 0.0
    if after_c_total >= 2:
        unprovoked_rate = after_c_d / float(after_c_total)

    if opp_rate > 0.9 and recent_rate >= 0.9:
        exploit += 0.03
    if opp_rate > 0.95 and recent_rate >= 0.95:
        exploit += 0.04
    if after_d_total >= 3 and forgive_rate >= 0.6 and unprovoked_rate <= 0.1:
        exploit += 0.12
    if after_d_total >= 6 and forgive_rate >= 0.75 and recent_rate > 0.8:
        exploit += 0.10
    if n >= 94 and opp_rate > 0.6:
        exploit += 0.08
    if n >= 97 and opp_rate > 0.4:
        exploit += 0.12
    if my_c > opp_c + 5 and opp_rate > 0.7:
        exploit += 0.02

    if exploit > 0.30:
        exploit = 0.30

    if rng.random() < exploit:
        return 'D'
    return 'C'
